    nodes.push(E("hairui_baguan", "批判《海瑞罢官》", "1965", "由姚文元撰文批判吴晗历史剧《海瑞罢官》引发的政治批判事件", "1965年11月10日，上海《文汇报》刊出姚文元《评新编历史剧〈海瑞罢官〉》，批判北京市副市长吴晗1960年创作的同名京剧。文章由江青、张春桥在上海组织写作，把剧中情节同「单干风」「翻案风」相联系。此文发表及由此引发的批判，被普遍视为文化大革命的导火线。", {"prov": "上海", "points": ["1965年11月10日，上海《文汇报》刊出姚文元《评新编历史剧〈海瑞罢官〉》", "文章由江青、张春桥在上海组织写作，把剧中情节同「单干风」「翻案风」相联系", "此文发表及由此引发的批判，被普遍视为文化大革命的导火线"], "y0": 1965, "y1": 1965}));
